def maximum_removals(s, p, removable):
    def is_subsequence_after_removal(k):
        removed = set(removable[:k])
        j = 0
        for i, ch in enumerate(s):
            if i in removed:
                continue
            if j < len(p) and ch == p[j]:
                j += 1
        return j == len(p)

    lo, hi = 0, len(removable)

    while lo < hi:
        mid = (lo + hi + 1) // 2
        if is_subsequence_after_removal(mid):
            lo = mid
        else:
            hi = mid - 1

    return lo

